const Scene2_FractionUsed: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Phase 1: all appear (0–40 frames)
  // Phase 2: unused fade to grey/dim (40–90 frames)
  // Phase 3: hold with only used ones bright (90+)

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill>
        {ALL_TAGS_DATA.map((item, i) => {
          const enterProgress = spring({
            frame,
            fps,
            delay: i * 2,
            config: { damping: 180 },
          });

          const dimProgress = interpolate(frame, [50, 85], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          const opacity = item.isUsed
            ? interpolate(enterProgress, [0, 1], [0, 1])
            : interpolate(enterProgress, [0, 1], [0, 1]) *
              (1 - dimProgress * 0.88);

          const color = item.isUsed
            ? COLORS.orange
            : `rgba(255,255,255,${interpolate(dimProgress, [0, 1], [0.7, 0.1])})`;

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: item.x,
                top: item.y,
                opacity,
                transform: `
                  translateY(${interpolate(enterProgress, [0, 1], [50, 0])}px)
                  scale(${interpolate(enterProgress, [0, 1], [0.85, 1])})
                `,
                fontSize: item.isUsed ? 62 : 48,
                fontWeight: item.isUsed ? 800 : 500,
                color,
                whiteSpace: "nowrap",
                textShadow: item.isUsed
                  ? `0 0 30px ${COLORS.orange}88`
                  : "none",
                transition: "none",
